// Real Big5 byte pairs. Keys are Unicode code points; values are bytes, not the code point.
(function () {
  var packed = "";
  var map = Object.create(null);
  for (var i = 0; i < packed.length; i += 8) {
    var cp = parseInt(packed.substr(i, 4), 16);
    map[cp] = [parseInt(packed.substr(i + 4, 2), 16), parseInt(packed.substr(i + 6, 2), 16)];
  }
  window.BIG5_BYTES = map;
})();
